        .chart-container { position: relative; height: 300px; margin: 20px 0; }
        .map-placeholder { background: linear-gradient(135deg, #ecf0f1, #d5dbdb); height: 250px; border-radius: 8px; display: flex; align-items: center; justify-content: center; color: #7f8c8d; font-size: 1.1em; }
        .heatmap-grid { display: grid; grid-template-columns: repeat(8, 1fr); gap: 4px; margin: 20px 0; }
        .heatmap-cell { padding: 15px 5px; text-align: center; font-size: 0.8em; border-radius: 4px; color: white; font-weight: 600; }
        .recommendation { background: white; border-left: 4px solid #27ae60; padding: 15px 20px; margin: 10px 0; border-radius: 0 8px 8px 0; box-shadow: 0 1px 5px rgba(0,0,0,0.1); }
        .recommendation h4 { color: #27ae60; margin-bottom: 8px; }
        .footer { text-align: center; padding: 20px; color: #7f8c8d; font-size: 0.9em; }
        @media (max-width: 900px) { .grid-2, .grid-3 { grid-template-columns: 1fr; } .kpi-dashboard { grid-template-columns: repeat(2, 1fr); } }
        @media (max-width: 600px) { .kpi-dashboard { grid-template-columns: 1fr; } }
    </style>
